-- DESIGN reference v1.1. A02b implements a versioned migration from this DDL.
-- UTC timestamps: RFC3339 Z; IDs: generated by server; JSON canonicalization: design §5.
PRAGMA foreign_keys = ON;
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE accounts(id TEXT PRIMARY KEY, name TEXT NOT NULL, row_version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE app_sessions(id TEXT PRIMARY KEY, csrf_hash TEXT NOT NULL, capability TEXT NOT NULL CHECK(capability IN ('creator','operator')), expires_at TEXT NOT NULL);
CREATE TABLE tasks(
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), input_json TEXT NOT NULL CHECK(json_valid(input_json)),
 state TEXT NOT NULL CHECK(state IN ('DRAFT','PLANNING','WAITING_CONFIRMATION','QUEUED','GENERATING','VALIDATING','REVISING','EXPORTING','READY','ACCEPTED','WAITING_INPUT','NEEDS_REVIEW','FAILED','INTERRUPTED','CANCELLED')),
 mode TEXT NOT NULL CHECK(mode IN ('mock','live')),
 row_version INTEGER NOT NULL DEFAULT 0 CHECK(row_version>=0), current_run_id TEXT,
 current_brief_version INTEGER, head_version_id TEXT, ready_version_id TEXT, accepted_version_id TEXT,
 pending_json TEXT CHECK(pending_json IS NULL OR json_valid(pending_json)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 UNIQUE(account_id,id)
);
CREATE TABLE materials(
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL, task_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('user_supplied_experience','source_text','existing_draft')),
 label TEXT NOT NULL, text TEXT NOT NULL, source_url TEXT, content_hash TEXT NOT NULL CHECK(length(content_hash)=64), authorized_at TEXT NOT NULL,
 FOREIGN KEY(account_id,task_id) REFERENCES tasks(account_id,id), UNIQUE(task_id,id)
);
CREATE TABLE briefs(
 task_id TEXT NOT NULL REFERENCES tasks(id), version INTEGER NOT NULL CHECK(version>=1), body_json TEXT NOT NULL CHECK(json_valid(body_json)),
 brief_hash TEXT NOT NULL CHECK(length(brief_hash)=64), rule_json TEXT NOT NULL CHECK(json_valid(rule_json)), confirmed_at TEXT, created_at TEXT NOT NULL,
 PRIMARY KEY(task_id,version), UNIQUE(task_id,brief_hash)
);
CREATE TABLE runs(
 id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), kind TEXT NOT NULL CHECK(kind IN ('content','revision','export','preview','scout')),
 state TEXT NOT NULL CHECK(state IN ('QUEUED','RUNNING','WAITING','SUCCEEDED','FAILED','INTERRUPTED','CANCELLED')),
 mode TEXT NOT NULL CHECK(mode IN ('mock','live')),
 phase TEXT NOT NULL, brief_version INTEGER, brief_hash TEXT, base_version_id TEXT,
 row_version INTEGER NOT NULL DEFAULT 0, repair_count INTEGER NOT NULL DEFAULT 0 CHECK(repair_count BETWEEN 0 AND 1),
 calls_reserved INTEGER NOT NULL DEFAULT 0 CHECK(calls_reserved>=0), retry_used INTEGER NOT NULL DEFAULT 0 CHECK(retry_used>=0),
 token_known INTEGER NOT NULL DEFAULT 0 CHECK(token_known>=0), token_reserved INTEGER NOT NULL DEFAULT 0 CHECK(token_reserved>=0),
 active_ms INTEGER NOT NULL DEFAULT 0 CHECK(active_ms>=0), limits_json TEXT NOT NULL CHECK(json_valid(limits_json)),
 lease_owner TEXT, lease_epoch INTEGER NOT NULL DEFAULT 0, lease_until TEXT, checkpoint_step TEXT, error_json TEXT,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL, started_at TEXT, finished_at TEXT, queue_seq INTEGER UNIQUE,
 FOREIGN KEY(task_id,brief_version) REFERENCES briefs(task_id,version), UNIQUE(task_id,id), CHECK(state!='QUEUED' OR queue_seq IS NOT NULL)
);
CREATE INDEX ix_runs_queue ON runs(state,queue_seq,id);
CREATE TABLE queue_sequence(id INTEGER PRIMARY KEY CHECK(id=1), next_seq INTEGER NOT NULL);
INSERT INTO queue_sequence VALUES(1,0);
CREATE UNIQUE INDEX uq_one_running_run ON runs((1)) WHERE state='RUNNING';
CREATE UNIQUE INDEX uq_active_revision ON runs(task_id) WHERE kind='revision' AND state IN ('QUEUED','RUNNING','WAITING','INTERRUPTED');
CREATE TABLE worker_slot(id INTEGER PRIMARY KEY CHECK(id=1), owner TEXT, epoch INTEGER NOT NULL DEFAULT 0, lease_until TEXT);
INSERT INTO worker_slot(id) VALUES(1);
CREATE TABLE checkpoints(
 task_id TEXT NOT NULL, run_id TEXT NOT NULL, step TEXT NOT NULL, attempt INTEGER NOT NULL CHECK(attempt>=1),
 status TEXT NOT NULL CHECK(status IN ('reserved','committed','rejected','unknown')), input_hash TEXT NOT NULL,
 output_ref TEXT, output_hash TEXT, error_json TEXT, created_at TEXT NOT NULL,
 PRIMARY KEY(task_id,run_id,step,attempt), FOREIGN KEY(task_id,run_id) REFERENCES runs(task_id,id)
);
CREATE TABLE model_calls(
 id TEXT PRIMARY KEY, task_id TEXT NOT NULL, run_id TEXT NOT NULL, step TEXT NOT NULL, attempt INTEGER NOT NULL,
 role TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('mock','live')), model_id TEXT NOT NULL, prompt_hash TEXT NOT NULL,
 input_hash TEXT NOT NULL, conditions_hash TEXT, status TEXT NOT NULL CHECK(status IN ('reserved','sent','received','failed','unknown','discarded')),
 provider_request_id TEXT, response_hash TEXT, reserved_tokens INTEGER NOT NULL DEFAULT 0 CHECK(reserved_tokens>=0), lease_epoch INTEGER NOT NULL, started_at TEXT NOT NULL, finished_at TEXT,
 FOREIGN KEY(task_id,run_id,step,attempt) REFERENCES checkpoints(task_id,run_id,step,attempt), UNIQUE(run_id,step,attempt)
);
CREATE TABLE usage_ledger(
 call_id TEXT PRIMARY KEY REFERENCES model_calls(id), input_tokens INTEGER CHECK(input_tokens>=0), output_tokens INTEGER CHECK(output_tokens>=0),
 total_tokens INTEGER CHECK(total_tokens>=0), cached_tokens INTEGER CHECK(cached_tokens>=0), reasoning_tokens INTEGER CHECK(reasoning_tokens>=0),
 usage_status TEXT NOT NULL CHECK(usage_status IN ('known','unknown')), cost_status TEXT NOT NULL CHECK(cost_status IN ('known','unpriced','unknown')),
 amount_minor INTEGER CHECK(amount_minor>=0), currency TEXT, price_version TEXT, updated_at TEXT NOT NULL,
 CHECK((usage_status='unknown' AND input_tokens IS NULL AND output_tokens IS NULL AND total_tokens IS NULL) OR (usage_status='known' AND input_tokens IS NOT NULL AND output_tokens IS NOT NULL AND total_tokens IS NOT NULL)),
 CHECK((cost_status='known' AND amount_minor IS NOT NULL AND currency IS NOT NULL) OR (cost_status!='known' AND amount_minor IS NULL))
);
CREATE TABLE task_events(
 id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), run_id TEXT NOT NULL, seq INTEGER NOT NULL CHECK(seq>=1),
 type TEXT NOT NULL, step TEXT NOT NULL, state TEXT NOT NULL, summary TEXT NOT NULL, refs_json TEXT NOT NULL CHECK(json_valid(refs_json)), created_at TEXT NOT NULL,
 FOREIGN KEY(task_id,run_id) REFERENCES runs(task_id,id), UNIQUE(task_id,seq)
);
CREATE TABLE content_versions(
 id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), run_id TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=1),
 parent_id TEXT, brief_version INTEGER NOT NULL, brief_hash TEXT NOT NULL, content_json TEXT NOT NULL CHECK(json_valid(content_json)),
 content_hash TEXT NOT NULL CHECK(length(content_hash)=64), created_at TEXT NOT NULL,
 FOREIGN KEY(task_id,run_id) REFERENCES runs(task_id,id), FOREIGN KEY(task_id,brief_version) REFERENCES briefs(task_id,version),
 UNIQUE(task_id,id), UNIQUE(task_id,ordinal), FOREIGN KEY(task_id,parent_id) REFERENCES content_versions(task_id,id)
);
CREATE TABLE rule_reports(id TEXT PRIMARY KEY, task_id TEXT NOT NULL, version_id TEXT NOT NULL, rule_version TEXT NOT NULL, passed INTEGER NOT NULL CHECK(passed IN (0,1)), body_json TEXT NOT NULL CHECK(json_valid(body_json)), FOREIGN KEY(task_id,version_id) REFERENCES content_versions(task_id,id), UNIQUE(version_id,rule_version));
CREATE TABLE editorial_reviews(id TEXT PRIMARY KEY, task_id TEXT NOT NULL, version_id TEXT NOT NULL, call_id TEXT NOT NULL UNIQUE REFERENCES model_calls(id), overall TEXT NOT NULL CHECK(overall IN ('pass','revise','needs_input')), body_json TEXT NOT NULL CHECK(json_valid(body_json)), FOREIGN KEY(task_id,version_id) REFERENCES content_versions(task_id,id));
CREATE TABLE export_batches(id TEXT PRIMARY KEY, task_id TEXT NOT NULL, version_id TEXT NOT NULL, run_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','committed','failed')), formats_json TEXT NOT NULL CHECK(json_valid(formats_json)), FOREIGN KEY(task_id,version_id) REFERENCES content_versions(task_id,id), FOREIGN KEY(task_id,run_id) REFERENCES runs(task_id,id));
CREATE TABLE artifacts(
 id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES export_batches(id), task_id TEXT NOT NULL, version_id TEXT NOT NULL, format TEXT NOT NULL CHECK(format IN ('md','txt')),
 relative_path TEXT NOT NULL UNIQUE, file_hash TEXT NOT NULL CHECK(length(file_hash)=64), byte_size INTEGER NOT NULL CHECK(byte_size>0),
 status TEXT NOT NULL CHECK(status IN ('available','missing','corrupt')), FOREIGN KEY(task_id,version_id) REFERENCES content_versions(task_id,id), UNIQUE(batch_id,format)
);
CREATE TABLE acceptances(id TEXT PRIMARY KEY, task_id TEXT NOT NULL, version_id TEXT NOT NULL, content_hash TEXT NOT NULL, session_id TEXT NOT NULL REFERENCES app_sessions(id), accepted_at TEXT NOT NULL, FOREIGN KEY(task_id,version_id) REFERENCES content_versions(task_id,id), UNIQUE(task_id,version_id));
CREATE TABLE feedback(id TEXT PRIMARY KEY, account_id TEXT NOT NULL, task_id TEXT NOT NULL, version_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('accept','reject','edit_request','real_platform_feedback')), evidence_kind TEXT NOT NULL CHECK(evidence_kind IN ('user_statement','real_feedback_unverified')), body_json TEXT NOT NULL CHECK(json_valid(body_json)), created_at TEXT NOT NULL, FOREIGN KEY(account_id,task_id) REFERENCES tasks(account_id,id), FOREIGN KEY(task_id,version_id) REFERENCES content_versions(task_id,id));
CREATE TABLE orders(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), origin TEXT NOT NULL CHECK(origin IN ('trial','simulation','real')), amount_minor INTEGER NOT NULL CHECK(amount_minor>=0), currency TEXT NOT NULL CHECK(currency='CNY'), payment_state TEXT NOT NULL CHECK(payment_state IN ('not_applicable','unpaid','confirmed')), row_version INTEGER NOT NULL DEFAULT 0, CHECK((origin='real' AND payment_state IN ('unpaid','confirmed')) OR (origin!='real' AND payment_state='not_applicable')));
CREATE TABLE receipts(id TEXT PRIMARY KEY, order_id TEXT NOT NULL UNIQUE REFERENCES orders(id), amount_minor INTEGER NOT NULL CHECK(amount_minor>0), currency TEXT NOT NULL CHECK(currency='CNY'), evidence_ref TEXT NOT NULL, confirmed_by_session TEXT NOT NULL REFERENCES app_sessions(id), confirmed_at TEXT NOT NULL);
CREATE TRIGGER immutable_order_origin BEFORE UPDATE OF origin ON orders WHEN OLD.origin!=NEW.origin BEGIN SELECT RAISE(ABORT,'immutable order origin'); END;
CREATE TRIGGER real_receipt_only BEFORE INSERT ON receipts WHEN NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.order_id AND origin='real' AND payment_state='unpaid' AND amount_minor=NEW.amount_minor AND currency=NEW.currency) BEGIN SELECT RAISE(ABORT,'receipt scope or amount mismatch'); END;
CREATE TABLE memories(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), kind TEXT NOT NULL CHECK(kind IN ('user_preference','observed_feedback','simulation_hypothesis')), statement TEXT NOT NULL, source_ref TEXT NOT NULL, observed_at TEXT NOT NULL, applicability TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','superseded','withdrawn')), supersedes_id TEXT, row_version INTEGER NOT NULL DEFAULT 0, UNIQUE(account_id,id), FOREIGN KEY(account_id,supersedes_id) REFERENCES memories(account_id,id));
CREATE INDEX ix_memories_lookup ON memories(account_id,status,kind,observed_at);
CREATE TABLE scouts(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), run_id TEXT NOT NULL REFERENCES runs(id), material_ids_json TEXT NOT NULL CHECK(json_valid(material_ids_json)), result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json)));
CREATE TABLE preview_scenarios(id TEXT PRIMARY KEY, scenario_hash TEXT NOT NULL UNIQUE, body_json TEXT NOT NULL CHECK(json_valid(body_json)));
CREATE TABLE preview_runs(
 id TEXT PRIMARY KEY, task_id TEXT NOT NULL, version_id TEXT NOT NULL, run_id TEXT NOT NULL UNIQUE, content_hash TEXT NOT NULL, scenario_id TEXT NOT NULL REFERENCES preview_scenarios(id),
 conditions_hash TEXT NOT NULL, conditions_json TEXT NOT NULL CHECK(json_valid(conditions_json)),
 state TEXT NOT NULL CHECK(state IN ('QUEUED','RUNNING','COMPLETED','CANCELLED','FAILED','INTERRUPTED','INCOMPLETE')),
 row_version INTEGER NOT NULL DEFAULT 0, analysis_status TEXT NOT NULL CHECK(analysis_status IN ('pending','succeeded','failed','skipped')), metrics_json TEXT CHECK(metrics_json IS NULL OR json_valid(metrics_json)),
 FOREIGN KEY(task_id,version_id) REFERENCES content_versions(task_id,id), FOREIGN KEY(task_id,run_id) REFERENCES runs(task_id,id), UNIQUE(task_id,id)
);
CREATE TABLE preview_segments(preview_id TEXT NOT NULL REFERENCES preview_runs(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), segment_id TEXT NOT NULL, kind TEXT NOT NULL, text TEXT NOT NULL, source_segment_id TEXT, PRIMARY KEY(preview_id,ordinal), UNIQUE(preview_id,segment_id));
CREATE TABLE audience_sessions(id TEXT PRIMARY KEY, preview_id TEXT NOT NULL REFERENCES preview_runs(id), persona_id TEXT NOT NULL, persona_json TEXT NOT NULL CHECK(json_valid(persona_json)), cursor INTEGER NOT NULL DEFAULT 0 CHECK(cursor>=0), outcome TEXT NOT NULL CHECK(outcome IN ('pending','active','completed','exited','incomplete')), stop_reason TEXT, UNIQUE(preview_id,persona_id), UNIQUE(preview_id,id));
CREATE TABLE audience_events(id TEXT PRIMARY KEY, preview_id TEXT NOT NULL, session_id TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), preview_seq INTEGER NOT NULL CHECK(preview_seq>=1), segment_id TEXT NOT NULL, call_id TEXT NOT NULL UNIQUE REFERENCES model_calls(id), body_json TEXT NOT NULL CHECK(json_valid(body_json)), action TEXT NOT NULL CHECK(action IN ('continue','exit')), created_at TEXT NOT NULL, FOREIGN KEY(preview_id,session_id) REFERENCES audience_sessions(preview_id,id), FOREIGN KEY(preview_id,segment_id) REFERENCES preview_segments(preview_id,segment_id), UNIQUE(session_id,ordinal), UNIQUE(preview_id,preview_seq));
CREATE TABLE analyses(id TEXT PRIMARY KEY, preview_id TEXT NOT NULL REFERENCES preview_runs(id), call_id TEXT NOT NULL UNIQUE REFERENCES model_calls(id), body_json TEXT NOT NULL CHECK(json_valid(body_json)));
CREATE TABLE revision_requests(id TEXT PRIMARY KEY, task_id TEXT NOT NULL, base_version_id TEXT NOT NULL, analysis_id TEXT NOT NULL REFERENCES analyses(id), run_id TEXT NOT NULL UNIQUE REFERENCES runs(id), selection_json TEXT NOT NULL CHECK(json_valid(selection_json)), output_version_id TEXT, FOREIGN KEY(task_id,base_version_id) REFERENCES content_versions(task_id,id), FOREIGN KEY(task_id,output_version_id) REFERENCES content_versions(task_id,id));
CREATE TABLE revision_changes(id TEXT PRIMARY KEY, revision_id TEXT NOT NULL REFERENCES revision_requests(id), finding_id TEXT, issue_id TEXT, old_segment_id TEXT NOT NULL, new_segment_id TEXT NOT NULL, change TEXT NOT NULL CHECK(change IN ('replace','delete','insert_after','move','metadata_update')), reason TEXT NOT NULL, CHECK((finding_id IS NULL) != (issue_id IS NULL)));
CREATE TABLE comparisons(id TEXT PRIMARY KEY, left_preview_id TEXT NOT NULL REFERENCES preview_runs(id), right_preview_id TEXT NOT NULL REFERENCES preview_runs(id), conditions_match INTEGER NOT NULL CHECK(conditions_match IN (0,1)), differences_json TEXT NOT NULL CHECK(json_valid(differences_json)), aligned_json TEXT NOT NULL CHECK(json_valid(aligned_json)), created_at TEXT NOT NULL);
CREATE TABLE experiments(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), left_preview_id TEXT NOT NULL, right_preview_id TEXT NOT NULL, planned_order_json TEXT NOT NULL CHECK(json_valid(planned_order_json)), conditions_hash TEXT NOT NULL, scenario_hash TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(task_id,left_preview_id) REFERENCES preview_runs(task_id,id), FOREIGN KEY(task_id,right_preview_id) REFERENCES preview_runs(task_id,id), CHECK(left_preview_id!=right_preview_id));
CREATE TABLE idempotency(scope TEXT NOT NULL, operation TEXT NOT NULL, key TEXT NOT NULL, request_hash TEXT NOT NULL, http_status INTEGER, response_json TEXT, created_at TEXT NOT NULL, PRIMARY KEY(scope,operation,key));
CREATE TRIGGER immutable_content BEFORE UPDATE ON content_versions BEGIN SELECT RAISE(ABORT,'immutable content version'); END;
CREATE TRIGGER immutable_brief_body BEFORE UPDATE OF body_json,brief_hash,rule_json ON briefs BEGIN SELECT RAISE(ABORT,'immutable brief'); END;
CREATE TRIGGER immutable_audience_event BEFORE UPDATE ON audience_events BEGIN SELECT RAISE(ABORT,'immutable audience event'); END;
CREATE INDEX ix_task_events_read ON task_events(task_id,seq);
CREATE INDEX ix_versions_read ON content_versions(task_id,ordinal);
CREATE INDEX ix_events_preview ON audience_events(preview_id,session_id,ordinal);
